"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[730],{56820:e=>{e.exports=JSON.parse('{"functions":[{"name":"get","desc":"Resolves `path` to a [Sound] without playing it, or returns `nil` if nothing\\nmatches.\\n\\nThe result is not parented, so parent it (or call [Sounds.play]) before it will be\\naudible \u2014 except for tree paths, which return the already-parented shared\\ninstance.","params":[{"name":"path","desc":"Sound to resolve","lua_type":"Path"},{"name":"options","desc":"Volume and loop overrides","lua_type":"SoundOptions?"}],"returns":[{"desc":"","lua_type":"Sound?"}],"function_type":"static","source":{"line":93,"path":"src/Shared/Class/Sounds.luau"}},{"name":"play","desc":"Resolves `path` and plays it immediately, returning the [Sound] so the caller can\\nstop it or wait on `Ended`.\\n\\nReturns `nil` when the path does not resolve \u2014 a missing sound is not an error.\\nNothing is cleaned up for you; a non-looping sound created from an asset id is\\nleft for the garbage collector once you drop the reference.\\n\\n```lua\\nSounds.play(\\"UI.Click\\")\\nSounds.play(1234567, { volume = 0.5, loop = true })\\n```","params":[{"name":"path","desc":"Sound to play","lua_type":"Path"},{"name":"options","desc":"Volume and loop overrides","lua_type":"SoundOptions?"}],"returns":[{"desc":"","lua_type":"Sound?"}],"function_type":"static","source":{"line":128,"path":"src/Shared/Class/Sounds.luau"}},{"name":"use","desc":"Hook-style variant: resolves the sound once and returns a play callback alongside\\nit, so a component can prepare a sound at mount and trigger it on demand.\\n\\nReturns nothing at all when the path does not resolve, so destructure defensively.\\n\\n```lua\\nlocal playClick = Sounds.use(\\"UI.Click\\")\\n\\nbutton.Activated:Connect(function()\\n\\tif playClick then\\n\\t\\tplayClick()\\n\\tend\\nend)\\n```","params":[{"name":"path","desc":"Sound to resolve","lua_type":"Path"},{"name":"options","desc":"Volume and loop overrides","lua_type":"SoundOptions?"}],"returns":[{"desc":"Play callback and the resolved sound","lua_type":"(() -> ()?, Sound?)"}],"function_type":"static","source":{"line":162,"path":"src/Shared/Class/Sounds.luau"}}],"properties":[],"types":[{"name":"Path","desc":"How a sound is addressed: a dotted [SoundService] path, an asset id number, or an\\n`rbxassetid://` string.","lua_type":"string | number","source":{"line":35,"path":"src/Shared/Class/Sounds.luau"}},{"name":"SoundOptions","desc":"Overrides applied after the sound is resolved. Both are only applied when truthy,\\nso `volume = 0` and `loop = false` leave the existing value alone.","fields":[{"name":"volume","lua_type":"number","desc":"Overrides the sound\'s volume"},{"name":"loop","lua_type":"boolean","desc":"Sets `Looped`"}],"source":{"line":46,"path":"src/Shared/Class/Sounds.luau"}}],"name":"Sounds","desc":"Resolves a sound from a flexible path and hands back a ready-to-play [Sound].\\n\\nA [Path] is either a dotted path into [SoundService] (`\\"UI.Click\\"`), a raw asset\\nid number, or an `rbxassetid://` string, so callers can name a curated sound or\\ndrop in an id without branching.\\n\\n:::caution Tree paths are not cloned\\nA dotted path returns the [Sound] living under SoundService itself, not a copy.\\nPlaying it twice in quick succession restarts the one instance rather than\\noverlapping, and any property you set on it sticks for every later caller.\\nNumeric ids build a fresh parentless Sound each time.\\n:::\\n\\n[PlaySFX] is the higher-level wrapper most gameplay code should reach for.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","source":{"line":22,"path":"src/Shared/Class/Sounds.luau"}}')}}]);